<?php
session_name('college_feedback_staff'); session_start(); require __DIR__ . '/includes/db.php';
$token = (string) ($_GET['token'] ?? $_POST['token'] ?? ''); $error = ''; $success = '';
$lookup = $pdo->prepare("SELECT rt.user_id, u.email FROM portal_reset_tokens rt JOIN portal_users u ON u.id = rt.user_id WHERE rt.token = :token AND rt.used_at IS NULL AND rt.expires_at > NOW() AND u.role = 'staff' LIMIT 1");
if ($token === '') $error = 'Reset token is missing.'; else { $lookup->execute([':token' => $token]); $record = $lookup->fetch(); if (!$record) $error = 'This password reset link has expired or is invalid.'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !$error) {
  $password = (string) ($_POST['password'] ?? ''); $confirm = (string) ($_POST['confirm_password'] ?? '');
  if (strlen($password) < 8) $error = 'Password must be at least 8 characters long.'; elseif ($password !== $confirm) $error = 'Passwords do not match.'; else {
    try { $pdo->beginTransaction(); $hash = password_hash($password, PASSWORD_DEFAULT); $pdo->prepare("UPDATE portal_users SET password_hash = :hash WHERE id = :id AND role = 'staff'")->execute([':hash' => $hash, ':id' => $record['user_id']]); $pdo->prepare("UPDATE users SET password_hash = :hash, must_change_password = 0 WHERE LOWER(email) = LOWER(:email) AND role = 'staff'")->execute([':hash' => $hash, ':email' => $record['email']]); $used = $pdo->prepare('UPDATE portal_reset_tokens SET used_at = NOW() WHERE token = :token AND used_at IS NULL'); $used->execute([':token' => $token]); if ($used->rowCount() !== 1) throw new RuntimeException('Token already used.'); $pdo->commit(); $success = 'Your password was updated successfully.'; } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); error_log('Staff password reset failed: ' . $e->getMessage()); $error = 'Unable to update your password right now. Please try again.'; }
  }
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set Password | Staff Portal</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:wght@600;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="../admin-portal/css/admin.css"></head><body class="login-body"><main class="login-shell"><section class="login-showcase"><div class="login-orb login-orb-one"></div><div class="login-orb login-orb-two"></div><div class="login-grid"></div><div class="login-showcase-brand"><span class="brand-mark login-mark"><img class="brand-logo" src="../assets/logo.svg" alt=""></span><span>College Feedback<small>Patan Nistha Campus</small></span></div></section><section class="login-panel"><div class="login-content recovery-content"><div class="login-brand"><span class="brand-mark"><img class="brand-logo" src="../assets/logo.svg" alt=""></span><span><strong>Staff Portal</strong><small>College Feedback System</small></span></div><div class="login-title recovery-title"><span class="page-kicker">ACCOUNT RECOVERY</span><h1>Choose a new password</h1><p>Use a secure password to protect your staff account.</p></div><?php if ($error): ?><div class="alert alert-error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></div><?php endif; ?><?php if ($success): ?><div class="otp-sent"><span class="otp-check">✓</span><span><?php echo htmlspecialchars($success, ENT_QUOTES, 'UTF-8'); ?></span></div><p class="recovery-back"><a href="login.php">← Back to sign in</a></p><?php elseif (!$error): ?><form method="post" class="recovery-verify-form"><input type="hidden" name="token" value="<?php echo htmlspecialchars($token, ENT_QUOTES, 'UTF-8'); ?>"><div class="field"><label for="password">New password</label><input id="password" type="password" name="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label for="confirm_password">Confirm new password</label><input id="confirm_password" type="password" name="confirm_password" minlength="8" autocomplete="new-password" required></div><button class="btn btn-primary btn-block" type="submit">Update password</button></form><?php endif; ?></div></section></main></body></html>
